l_int32 generate_html_image_viewer(const char *dirin, const char *dirout, const char *rootname, l_int32 thumbwidth, l_int32 viewwidth) {
    l_int32 result = 0;
    char *outdir_path = NULL;

    // Check for valid input parameters
    if (!dirin || !dirout || !rootname || thumbwidth <= 0 || viewwidth <= 0) {
        return 1; // Error code for invalid input
    }

    // Create the output directory if it doesn't exist
    if ((result = makePath(dirout)) != 0) {
        return result;
    }

    // Retrieve filenames from the input directory
    SARRAY *filenames = getFilenames(dirin);
    if (!filenames) {
        return 2; // Error code for failure to get filenames
    }

    // Generate thumbnails and view images for each image file
    for (l_int32 i = 0; i < sarrayGetCount(filenames); ++i) {
        const char *filename = sarrayGetString(filenames, i, L_NOCOPY);
        char *fullpath = genPathname(dirin, filename);
        if (!fullpath) {
            continue;
        }

        // Load image
        PIX *pix = pixRead(fullpath);
        if (!pix) {
            FREE(fullpath);
            continue;
        }

        // Generate thumbnail
        PIX *thumb = pixScaleToWidth(pix, thumbwidth);
        if (thumb) {
            char *thumb_outpath = genPathname(dirout, filename);
            if (thumb_outpath) {
                char *thumb_out = stringJoin(thumb_outpath, "_thumb");
                pixWrite(thumb_out, thumb, IFF_JPEG);
                FREE(thumb_outpath);
                FREE(thumb_out);
            }
            pixDestroy(&thumb);
        }

        // Generate viewable image
        PIX *view = pixScaleToWidth(pix, viewwidth);
        if (view) {
            char *view_outpath = genPathname(dirout, filename);
            if (view_outpath) {
                char *view_out = stringJoin(view_outpath, "_view");
                pixWrite(view_out, view, IFF_JPEG);
                FREE(view_outpath);
                FREE(view_out);
            }
            pixDestroy(&view);
        }

        pixDestroy(&pix);
        FREE(fullpath);
    }

    // Generate HTML files
    // HTML with thumbnails
    {
        char *thumb_html_path = stringJoin(dirout, rootname);
        if (thumb_html_path) {
            char *thumb_html = stringJoin(thumb_html_path, "_thumbs.html");
            FILE *fp = fopen(thumb_html, "w");
            if (fp) {
                fprintf(fp, "<html><body>\n");
                for (l_int32 i = 0; i < sarrayGetCount(filenames); ++i) {
                    const char *filename = sarrayGetString(filenames, i, L_NOCOPY);
                    char *base = stringClone(filename);
                    char *thumbname = replaceSubString(base, ".jpg", "_thumb.jpg", NULL);
                    char *viewname = replaceSubString(base, ".jpg", "_view.jpg", NULL);
                    fprintf(fp, "<a href=\"%s\"><img src=\"%s\"></a>\n", viewname, thumbname);
                    FREE(base);
                    FREE(thumbname);
                    FREE(viewname);
                }
                fprintf(fp, "</body></html>\n");
                fclose(fp);
            }
            FREE(thumb_html_path);
            FREE(thumb_html);
        }
    }

    // HTML with links to view images
    {
        char *view_html_path = stringJoin(dirout, rootname);
        if (view_html_path) {
            char *view_html = stringJoin(view_html_path, "_views.html");
            FILE *fp = fopen(view_html, "w");
            if (fp) {
                fprintf(fp, "<html><body>\n");
                for (l_int32 i = 0; i < sarrayGetCount(filenames); ++i) {
                    const char *filename = sarrayGetString(filenames, i, L_NOCOPY);
                    char *base = stringClone(filename);
                    char *viewname = replaceSubString(base, ".jpg", "_view.jpg", NULL);
                    fprintf(fp, "<a href=\"%s\">View Image %d</a><br>\n", viewname, i + 1);
                    FREE(base);
                    FREE(viewname);
                }
                fprintf(fp, "</body></html>\n");
                fclose(fp);
            }
            FREE(view_html_path);
            FREE(view_html);
        }
    }

    sarrayDestroy(&filenames);

    return result;
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <dirent.h>
#include <sys/stat.h>
#include <unistd.h>

#include "pix.h"
#include "allheaders.h"

l_int32 generate_html_viewer(const char* dirin, const char* dirout, const char* rootname,
                             l_int32 thumbwidth, l_int32 viewwidth) {
    // Validate input parameters
    if (!dirin || !dirout || !rootname) {
        fprintf(stderr, "Invalid input parameters.\n");
        return 1;
    }

    if (thumbwidth <= 0 || viewwidth <= 0) {
        fprintf(stderr, "Invalid thumbnail or view width.\n");
        return 1;
    }

    // Create output directory if it doesn't exist
    struct stat st;
    if (stat(dirout, &st) == -1) {
        if (mkdir(dirout, 0755) == -1) {
            perror("Failed to create output directory");
            return 1;
        }
    }

    // Open input directory
    DIR* dp = opendir(dirin);
    if (!dp) {
        perror("Failed to open input directory");
        return 1;
    }

    // Read image files from input directory
    char** filelist = NULL;
    l_int32 count = 0;
    struct dirent* entry;
    while ((entry = readdir(dp)) != NULL) {
        if (entry->d_type == DT_REG) {
            char* filename = entry->d_name;
            if (isImageFile(filename)) {
                l_int32 len = strlen(dirin) + 1 + strlen(filename) + 1;
                char* fullpath = (char*)malloc(len);
                if (!fullpath) {
                    fprintf(stderr, "Memory allocation failed.\n");
                    closedir(dp);
                    return 1;
                }
                snprintf(fullpath, len, "%s/%s", dirin, filename);
                filelist = (char**)realloc(filelist, (count + 1) * sizeof(char*));
                if (!filelist) {
                    fprintf(stderr, "Memory allocation failed.\n");
                    free(fullpath);
                    closedir(dp);
                    return 1;
                }
                filelist[count++] = fullpath;
            }
        }
    }
    closedir(dp);

    if (count == 0) {
        fprintf(stderr, "No image files found in input directory.\n");
        for (l_int32 i = 0; i < count; ++i) {
            free(filelist[i]);
        }
        free(filelist);
        return 1;
    }

    // Generate thumbnails and view images
    char thumbpath[256];
    char viewpath[256];
    for (l_int32 i = 0; i < count; ++i) {
        char* filename = filelist[i];
        PIX* pix = pixRead(filename);
        if (!pix) {
            fprintf(stderr, "Failed to read image file: %s\n", filename);
            continue;
        }

        // Generate thumbnail
        PIX* pixthumb = pixScaleToWidth(pix, thumbwidth);
        if (!pixthumb) {
            fprintf(stderr, "Failed to generate thumbnail for: %s\n", filename);
            pixDestroy(&pix);
            continue;
        }

        // Save thumbnail
        l_int32 thumbid = i + 1;
        snprintf(thumbpath, sizeof(thumbpath), "%s/%s_thumb%03d.png", dirout, rootname, thumbid);
        if (pixWrite(thumbpath, pixthumb, IFF_PNG) != 0) {
            fprintf(stderr, "Failed to write thumbnail: %s\n", thumbpath);
        }
        pixDestroy(&pixthumb);

        // Generate view image
        PIX* pixview = pixScaleToWidth(pix, viewwidth);
        if (!pixview) {
            fprintf(stderr, "Failed to generate view image for: %s\n", filename);
            pixDestroy(&pix);
            continue;
        }

        // Save view image
        l_int32 viewid = i + 1;
        snprintf(viewpath, sizeof(viewpath), "%s/%s_view%03d.png", dirout, rootname, viewid);
        if (pixWrite(viewpath, pixview, IFF_PNG) != 0) {
            fprintf(stderr, "Failed to write view image: %s\n", viewpath);
        }
        pixDestroy(&pixview);

        pixDestroy(&pix);
    }

    // Create HTML files
    char htmlpath[256];
    snprintf(htmlpath, sizeof(htmlpath), "%s/%s_index.html", dirout, rootname);
    FILE* htmlfile = fopen(htmlpath, "w");
    if (!htmlfile) {
        perror("Failed to open HTML file for writing");
        for (l_int32 i = 0; i < count; ++i) {
            free(filelist[i]);
        }
        free(filelist);
        return 1;
    }

    fprintf(htmlfile, "<html>\n");
    fprintf(htmlfile, "<head>\n");
    fprintf(htmlfile, "<title>%s</title>\n", rootname);
    fprintf(htmlfile, "</head>\n");
    fprintf(htmlfile, "<body>\n");
    fprintf(htmlfile, "<h1>%s</h1>\n", rootname);
    fprintf(htmlfile, "<ul>\n");

    for (l_int32 i = 0; i < count; ++i) {
        l_int32 thumbid = i + 1;
        l_int32 viewid = i + 1;
        snprintf(thumbpath, sizeof(thumbpath), "%s_thumb%03d.png", rootname, thumbid);
        snprintf(viewpath, sizeof(viewpath), "%s_view%03d.png", rootname, viewid);
        fprintf(htmlfile, "<li><a href=\"%s\"><img src=\"%s\" alt=\"Image %d\" /></a></li>\n",
                viewpath, thumbpath, i + 1);
    }

    fprintf(htmlfile, "</ul>\n");
    fprintf(htmlfile, "</body>\n");
    fprintf(htmlfile, "</html>\n");
    fclose(htmlfile);

    // Free resources
    for (l_int32 i = 0; i < count; ++i) {
        free(filelist[i]);
    }
    free(filelist);

    return 0;
}

l_int32 generateImageViewer(const char* dirin, const char* dirout, const char* rootname, l_int32 thumbwidth, l_int32 viewwidth) {
    l_int32 result = 0;
    l_int32 count = 0;
    char* outdirname = NULL;

    if (!dirin || !dirout || !rootname) {
        fprintf(stderr, "Invalid input parameters.\n");
        return 1;
    }

    outdirname = makePath(dirin, dirout);
    if (!outdirname) {
        fprintf(stderr, "Failed to create output directory path.\n");
        return 1;
    }

    if (makeDirectory(outdirname)) {
        fprintf(stderr, "Failed to create output directory.\n");
        LEPT_FREE(outdirname);
        return 1;
    }

    BOXA* boxa = readBoxFiles(dirin);
    if (!boxa) {
        fprintf(stderr, "No box files found.\n");
        LEPT_FREE(outdirname);
        return 1;
    }

    count = boxaGetCount(boxa);
    for (l_int32 i = 0; i < count; ++i) {
        BOX* box = boxaGetBox(boxa, i, L_COPY);
        char* fname = boxGetFilename(box);
        char* thumbpath = makePath(outdirname, fname);
        char* viewpath = makePath(outdirname, fname);

        Pix* pix = pixRead(fname);
        if (!pix) {
            fprintf(stderr, "Failed to read image: %s\n", fname);
            continue;
        }

        Pix* thumbpix = pixScaleToWidth(pix, thumbwidth);
        Pix* viewpix = pixScaleToWidth(pix, viewwidth);

        if (pixWrite(thumbpath, thumbpix, IFF_JP2K)) {
            fprintf(stderr, "Failed to write thumbnail image: %s\n", thumbpath);
        }

        if (pixWrite(viewpath, viewpix, IFF_JP2K)) {
            fprintf(stderr, "Failed to write viewable image: %s\n", viewpath);
        }

        pixDestroy(&pix);
        pixDestroy(&thumbpix);
        pixDestroy(&viewpix);
        LEPT_FREE(fname);
        LEPT_FREE(thumbpath);
        LEPT_FREE(viewpath);
    }

    char* html1 = makeHTMLFile(outdirname, rootname, 1);
    char* html2 = makeHTMLFile(outdirname, rootname, 2);

    if (!html1 || !html2) {
        fprintf(stderr, "Failed to generate HTML files.\n");
        result = 1;
    }

    boxaDestroy(&boxa);
    LEPT_FREE(outdirname);
    LEPT_FREE(html1);
    LEPT_FREE(html2);

    return result;
}

