l_int32 generateImageViewer(const char *dirin, const char *dirout, const char *rootname, l_int32 thumbwidth, l_int32 viewwidth) {
    char *outputDir;
    char *inputDir;
    char *indexHtmlPath;
    char *fullViewHtmlPath;
    char *thumbPath;
    char *viewPath;
    char *filename;
    char *outputFile;
    l_int32 result = 0;
    DIR *dir;
    struct dirent *entry;
    struct stat st;

    if (!dirin || !dirout || !rootname) {
        return 1;
    }

    inputDir = (char *)malloc(strlen(dirin) + 1);
    outputDir = (char *)malloc(strlen(dirout) + 1);
    strcpy(inputDir, dirin);
    strcpy(outputDir, dirout);

    // Ensure output directory exists
    if (stat(outputDir, &st) == -1) {
        if (mkdir(outputDir, 0755) == -1) {
            perror("Failed to create output directory");
            result = 1;
            goto cleanup;
        }
    }

    dir = opendir(inputDir);
    if (!dir) {
        perror("Failed to open input directory");
        result = 1;
        goto cleanup;
    }

    indexHtmlPath = (char *)malloc(strlen(dirout) + strlen("/index.html") + 1);
    fullViewHtmlPath = (char *)malloc(strlen(dirout) + strlen("/fullview.html") + 1);
    sprintf(indexHtmlPath, "%s/index.html", dirout);
    sprintf(fullViewHtmlPath, "%s/fullview.html", dirout);

    FILE *indexHtml = fopen(indexHtmlPath, "w");
    FILE *fullViewHtml = fopen(fullViewHtmlPath, "w");

    if (!indexHtml || !fullViewHtml) {
        perror("Failed to create HTML files");
        result = 1;
        goto cleanup;
    }

    fprintf(indexHtml, "<html><body><h1>Image Thumbnails</h1><ul>\n");
    fprintf(fullViewHtml, "<html><body><h1>Viewable Images</h1><ul>\n");

    while ((entry = readdir(dir)) != NULL) {
        if (entry->d_name[0] == '.') {
            continue;
        }

        filename = (char *)malloc(strlen(inputDir) + strlen("/") + strlen(entry->d_name) + 1);
        sprintf(filename, "%s/%s", inputDir, entry->d_name);

        // Assume generateThumbnail and generateViewImage are functions from leptola.h
        thumbPath = (char *)malloc(strlen(dirout) + strlen("/") + strlen(entry->d_name) + 6 + 1); // +6 for "_thumb.jpg"
        viewPath = (char *)malloc(strlen(dirout) + strlen("/") + strlen(entry->d_name) + 6 + 1); // +6 for "_view.jpg"
        sprintf(thumbPath, "%s/%s_thumb.jpg", dirout, entry->d_name);
        sprintf(viewPath, "%s/%s_view.jpg", dirout, entry->d_name);

        // Generate thumbnail and view image
        result = generateThumbnail(filename, thumbPath, thumbwidth);
        if (result != 0) {
            fprintf(stderr, "Failed to generate thumbnail for %s\n", entry->d_name);
            continue;
        }

        result = generateViewImage(filename, viewPath, viewwidth);
        if (result != 0) {
            fprintf(stderr, "Failed to generate view image for %s\n", entry->d_name);
            continue;
        }

        fprintf(indexHtml, "<li><a href=\"%s\"><img src=\"%s\" alt=\"%s\"></a></li>\n", viewPath, thumbPath, entry->d_name);
        fprintf(fullViewHtml, "<li><img src=\"%s\" alt=\"%s\"></li>\n", viewPath, entry->d_name);
    }

    fprintf(indexHtml, "</ul></body></html>\n");
    fprintf(fullViewHtml, "</ul></body></html>\n");

    fclose(indexHtml);
    fclose(fullViewHtml);
    closedir(dir);

cleanup:
    free(inputDir);
    free(outputDir);
    free(indexHtmlPath);
    free(fullViewHtmlPath);

    return result;
}
